WITH earned AS (
  SELECT t.game_id, t.trophy_id, t.trophy_type,
    ROW_NUMBER() OVER (ORDER BY t.earned_at ASC, t.game_id ASC, t.trophy_id ASC) AS trophy_number
  FROM trophies t
  WHERE t.earned = 1 AND t.earned_at IS NOT NULL
)
INSERT INTO trophy_preferences (game_id, trophy_id, state, updated_at, updated_by)
SELECT game_id, trophy_id, 'favorite', CURRENT_TIMESTAMP, 'legacy-sheet'
FROM earned
WHERE trophy_type <> 'platinum' AND trophy_number IN (
  1,14,17,295,300,317,322,328,330,397,606,742,862,909,1042,1043,1044,1045,1052,1087,
  1093,1132,1147,1148,1152,1192,1422,1500,1537,1616,1640,1893,1897,1913,2000,2048,2138,
  2279,2671,2689,2701,2750,2751,2753,2759,2766,2798,3010,3013,3014,3163,3272,3467,3578,
  3587,3676,3688,3717,3786,3921,3988,4362,4551,4555,4583,4584,4586,4748,4754,4780,4805,
  4807,4814,4823,4983,5055,5127,5186,5666,5699,5769,5817,5818,5849,5992,6065,6232,6489,
  6501,6565,6567,6708,6710,6847,6865,6866,6875,6889,6895,6897,6898,6910,6916,7039,7041,
  7094,7104,7108,7112,7113,7135,7257,7477,7488,8393,8602,8649,8748,8875,9006,9007,9119,
  9256,9261,9396,9481,9486,9495,9500,9521,9684,9720,9725,9750,9772,9837,9843,9844,9903,
  9978,9997,10000,10056,10059,10069,10119,10142,10159,10162,10167,10364,10546,10590,10611,
  10636,10674,10675,10682,10796,10862,10866,10867,10945,10964,11016,11093,11104,11118,
  11141,11150,11159,11162,11262,11347,11387,11463,11483,11530,11591,11592,11617,11619
)
ON CONFLICT(game_id, trophy_id) DO UPDATE SET state = 'favorite',
  updated_at = excluded.updated_at, updated_by = excluded.updated_by;
